#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* The original binary prints the following messages for error cases:
 *   NO_INPUT
 *   BAD_INPUT
 *   BAD_MODULUS
 *   OUT_OF_RANGE
 *   NEGATIVE_EXPONENT
 * and on success prints:  result=%lld\n
 * The program expects three decimal arguments: base exponent modulus.
 * It performs modular exponentiation (base^exponent mod modulus) with
 * exponent ≥ 0, modulus ≥ 1 and ≤ 1 000 000 000.
 */

int main(int argc, char **argv)
{
    /* -------------------------------------------------------------
       1. Argument count check
       ------------------------------------------------------------- */
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    /* -------------------------------------------------------------
       2. Parse the three arguments (base, exponent, modulus)
       ------------------------------------------------------------- */
    char *endptr;
    long long base, exp, mod;

    /* base */
    base = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0')
        goto bad_input;

    /* exponent */
    exp = strtoll(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0')
        goto bad_input;

    /* modulus */
    mod = strtoll(argv[3], &endptr, 10);
    if (endptr == argv[3] || *endptr != '\0')
        goto bad_input;

    /* -------------------------------------------------------------
       3. Validate modulus
       ------------------------------------------------------------- */
    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -------------------------------------------------------------
       4. Validate exponent
       ------------------------------------------------------------- */
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    /* -------------------------------------------------------------
       5. Modular exponentiation (base^exp % mod)
       ------------------------------------------------------------- */
    /* Reduce base into the range [0, mod‑1] */
    base %= mod;
    if (base < 0)
        base += mod;

    long long result = 1 % mod;   /* works even when mod == 1 */

    while (exp > 0) {
        if (exp & 1LL) {
            __int128 tmp = ( __int128) result * base;
            result = (long long)(tmp % mod);
        }
        __int128 tmp2 = ( __int128) base * base;
        base = (long long)(tmp2 % mod);
        exp >>= 1;
    }

    /* -------------------------------------------------------------
       6. Output the result
       ------------------------------------------------------------- */
    printf("result=%lld\n", result);
    return 0;

bad_input:
    puts("BAD_INPUT");
    return 0;
}
